def kurtosis_lebih(data):
    n = len(data)
    m = sum(data) / n
    s = (sum((v - m) ** 2 for v in data) / n) ** 0.5
    if s == 0:
        return None
    return round(sum(((v - m) / s) ** 4 for v in data) / n - 3, 4)

def bentuk(data):
    n = len(data)
    m = sum(data) / n
    s = (sum((v - m) ** 2 for v in data) / n) ** 0.5
    sk = 0.0 if s == 0 else sum(((v - m) / s) ** 3 for v in data) / n
    if sk > 0.5:
        return 'miring kanan'
    if sk < -0.5:
        return 'miring kiri'
    return 'simetris'

