def persentil(data, p):
    s = sorted(data)
    pos = (len(s) - 1) * p / 100
    lo = int(round(pos, 6))
    hi = min(lo + 1, len(s) - 1)
    return round(s[lo] + (s[hi] - s[lo]) * (pos - lo), 4)

def bowley(data):
    s = sorted(data)

    def kuantil(q):
        p = (len(s) - 1) * q
        lo = int(round(p, 6))
        hi = min(lo + 1, len(s) - 1)
        return s[lo] + (s[hi] - s[lo]) * (p - lo)

    q1, q2, q3 = kuantil(0.25), kuantil(0.5), kuantil(0.75)
    if q3 == q1:
        return 0.0
    return round((q3 + q1 - 2 * q2) / (q3 - q1), 4) + 0.0

